-- =====================================================================================
-- VERIFICATION (paste into Hasura -> Data -> SQL). Pure read-only. Run BEFORE and AFTER repair.
-- Embeds the 984-row authoritative truth (bd_id, wrong_l2_id, correct_l2_id, kind).
--   BEFORE repair: still_wrong should be ~984, resolved_clean ~0.
--   AFTER  prod_repair_full.sql: still_wrong=0, resolved_clean=978, boundary_pending=6.
--   AFTER  + boundary cascade:   resolved_clean=978, boundary_fixed=6, still_wrong=0.
-- =====================================================================================
CREATE TEMP TABLE _t (bd_id uuid PRIMARY KEY, wrong_l2_id uuid, correct_l2_id uuid, kind text) ON COMMIT DROP;

SELECT
  (SELECT count(*) FROM _t)                                                                       AS truth_rows,
  (SELECT count(*) FROM bridge_deposit bd JOIN _t t ON t.bd_id=bd.id
      WHERE bd.l2_transaction_id=t.wrong_l2_id)                                                   AS still_wrong,
  (SELECT count(*) FROM bridge_deposit bd JOIN _t t ON t.bd_id=bd.id
      WHERE t.kind='clean' AND bd.l2_transaction_id=t.correct_l2_id)                              AS resolved_clean,
  (SELECT count(*) FROM bridge_deposit bd JOIN _t t ON t.bd_id=bd.id
      WHERE t.kind='boundary' AND bd.l2_transaction_id=t.correct_l2_id)                           AS boundary_fixed,
  (SELECT count(*) FROM bridge_deposit bd JOIN _t t ON t.bd_id=bd.id
      WHERE t.kind='boundary' AND bd.l2_transaction_id IS NULL)                                   AS boundary_pending,
  (SELECT count(*) FROM bridge_deposit bd JOIN _t t ON t.bd_id=bd.id
      WHERE bd.l2_transaction_id IS NOT NULL
        AND bd.l2_transaction_id<>t.correct_l2_id AND bd.l2_transaction_id<>t.wrong_l2_id)        AS unexpected_other;
